import{_ as a,o as e,c as l,ag as r}from"./chunks/framework.DJVIMu25.js";const b=JSON.parse('{"title":"集成与挂钩","description":"","frontmatter":{"title":"集成与挂钩"},"headers":[],"relativePath":"zh_Hans/reference/integrations.md","filePath":"zh_Hans/reference/integrations.md","lastUpdated":1786545590000}'),d={name:"zh_Hans/reference/integrations.md"};function o(i,t,n,s,c,h){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="集成与挂钩" tabindex="-1">集成与挂钩 <a class="header-anchor" href="#集成与挂钩" aria-label="Permalink to &quot;集成与挂钩&quot;">​</a></h1><p>JoyMart 与多款流行的 Spigot/Paper 插件集成。所有集成为可选 —— JoyMart 会在启动时自动检测它们。</p><h2 id="placeholderapi" tabindex="-1">PlaceholderAPI <a class="header-anchor" href="#placeholderapi" aria-label="Permalink to &quot;PlaceholderAPI&quot;">​</a></h2><p>安装 PlaceholderAPI 后，JoyMart 会注册以下占位符：</p><table tabindex="0"><thead><tr><th>占位符</th><th>说明</th></tr></thead><tbody><tr><td><code>%gamebox_tokens%</code></td><td>当前玩家的代币余额</td></tr><tr><td><code>%gamebox_highscore_&lt;id&gt;%</code></td><td>当前玩家在某款游戏中的最高分（例如 <code>%gamebox_highscore_2048%</code>）</td></tr><tr><td><code>%gamebox_ingame%</code></td><td>当前玩家是否在游戏中（true/false）</td></tr></tbody></table><p>实现位于 <code>GameBoxPlaceholders.java</code>。检测到 PlaceholderAPI 时会自动注册占位符。</p><h2 id="vault-经济" tabindex="-1">Vault 经济 <a class="header-anchor" href="#vault-经济" aria-label="Permalink to &quot;Vault 经济&quot;">​</a></h2><p>当 Vault 存在且 config.yml 中 <code>economy.vault: true</code> 时：</p><ul><li>游戏可在发放代币的同时奖励金钱（金币）</li><li>代币商店可以收取金币</li><li>抽奖 / 老虎机奖池可包含金钱奖励</li><li>所有金钱操作都通过 Vault 的 Economy API 进行</li></ul><div class="warning custom-block"><p class="custom-block-title">注意</p><p>未安装 Vault 时，仅使用 JoyMart 内部的代币系统。</p></div><h2 id="calendarevents" tabindex="-1">CalendarEvents <a class="header-anchor" href="#calendarevents" aria-label="Permalink to &quot;CalendarEvents&quot;">​</a></h2><p>JoyMart 通过 CalendarEvents 实现季节性彩蛋。检测到 CalendarEvents 时：</p><ul><li>节假日期间可能会出现特殊的主题游戏图标或消息</li><li>挂钩位于 <code>CalendarEventsHook.java</code>，会自动检测 —— 无需任何配置</li></ul><h2 id="bstats" tabindex="-1">bStats <a class="header-anchor" href="#bstats" aria-label="Permalink to &quot;bStats&quot;">​</a></h2><p>JoyMart 使用 bStats 收集匿名使用统计：</p><ul><li>默认启用（可在 config.yml 中通过 <code>bstats: false</code> 禁用）</li><li>上报内容：服务器版本、插件版本、游戏使用情况、存储类型</li><li>数据发送至 <a href="https://bstats.org/" target="_blank" rel="noreferrer">bStats.org</a>，且完全匿名</li></ul><div class="tip custom-block"><p class="custom-block-title">提示</p><p>bStats 仅收集聚合的、匿名化的指标数据，不包含任何玩家个人信息或服务器敏感配置。</p></div><h2 id="软依赖汇总" tabindex="-1">软依赖汇总 <a class="header-anchor" href="#软依赖汇总" aria-label="Permalink to &quot;软依赖汇总&quot;">​</a></h2><table tabindex="0"><thead><tr><th>插件</th><th>是否必需</th><th>用途</th></tr></thead><tbody><tr><td>Vault</td><td>可选</td><td>经济挂钩（金币）</td></tr><tr><td>PlaceholderAPI</td><td>可选</td><td>占位符变量</td></tr><tr><td>CalendarEvents</td><td>可选</td><td>季节性彩蛋</td></tr><tr><td>bStats</td><td>内置</td><td>匿名指标</td></tr></tbody></table><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../guides/configuration">配置文件说明</a></li><li><a href="./scoring">计分与事件</a></li><li><a href="./api">公开 API</a></li></ul>',21)])])}const p=a(d,[["render",o]]);export{b as __pageData,p as default};
